styles:
::-webkit-scrollbar { display: none; }
body {
    font-family: 'Inter', sans-serif;
    background-color: #0B0D17;
    color: #F8FAFC;
    scroll-behavior: smooth;
}
.hero-glow {
    background: radial-gradient(circle at 50% 0%, rgba(212, 175, 55, 0.15), transparent 70%);
}
.glass-card {
    background: rgba(21, 24, 40, 0.6);
    backdrop-filter: blur(12px);
    border: 1px solid rgba(255, 255, 255, 0.08);
}
.gold-glow {
    box-shadow: 0 0 20px rgba(212, 175, 55, 0.2);
}
.blob-bg {
    background: radial-gradient(circle, rgba(212, 175, 55, 0.15) 0%, rgba(11, 13, 23, 0) 70%);
}
.nav-dropdown {
    display: none;
    position: absolute;
    top: 100%;
    left: 0;
    margin-top: 0.5rem;
    min-width: 200px;
    background: rgba(21, 24, 40, 0.95);
    backdrop-filter: blur(12px);
    border: 1px solid rgba(255, 255, 255, 0.08);
    border-radius: 12px;
    padding: 0.5rem;
    z-index: 100;
}
.nav-item:hover .nav-dropdown {
    display: block;
}

